#!/usr/bin/env bash
# Submits winget manifests to microsoft/winget-pkgs, through a fork.
#
# Usage: winget-submit.sh <dir>, where <dir> contains the manifests/ generated by GoReleaser.
# GH_TOKEN must be a classic token with the public_repo scope and write access to the fork.
set -euo pipefail

root=$1
fork=${WINGET_FORK:-upsun/winget-pkgs}
upstream=microsoft/winget-pkgs

if [ -z "${GH_TOKEN:-}" ]; then
  echo "::warning::GH_TOKEN is not set: skipping the winget submission"
  exit 0
fi

installer=$(find "$root/manifests" -name '*.installer.yaml' | head -n1)
if [ -z "$installer" ]; then
  echo "No winget manifests found in $root" >&2
  exit 1
fi
dir=$(dirname "$installer")
path=${dir#"$root"/} # e.g. manifests/u/Upsun/CLI/5.14.0
version=$(basename "$dir")
id=$(basename "$installer" .installer.yaml)
branch="$id-$version"
# Title formats from the winget-pkgs pull request template.
if gh api "repos/$upstream/contents/${path%/*}" >/dev/null 2>&1; then
  title="Update: $id to $version"
else
  title="New package: $id version $version"
fi

# A stale fork still works: the PR only adds files.
gh api -X POST "repos/$fork/merge-upstream" -f branch=master >/dev/null ||
  echo "::warning::Could not sync $fork with $upstream"
sha=$(gh api "repos/$fork/git/ref/heads/master" --jq .object.sha)
gh api "repos/$fork/git/refs" -f ref="refs/heads/$branch" -f sha="$sha" >/dev/null

for f in "$dir"/*.yaml; do
  gh api -X PUT "repos/$fork/contents/$path/$(basename "$f")" \
    -f message="$title" -f branch="$branch" -f content="$(base64 -w0 "$f")" >/dev/null
done

description="$id version $version, submitted by the release workflow of https://github.com/upsun/cli."
if body=$(gh api "repos/$upstream/contents/.github/PULL_REQUEST_TEMPLATE.md" -H 'Accept: application/vnd.github.raw'); then
  body=${body/"## 📖 Description"/"## 📖 Description"$'\n\n'"$description"}
else
  body=$description
fi
gh pr create --repo "$upstream" --base master --head "${fork%%/*}:$branch" --title "$title" \
  --body "$body"
